import{_ as t,o as s,c as i,a4 as a}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0065 — Cycle de vie des pages : le brouillon de page","description":"Extrait de docs/adr/0065-cycle-de-vie-des-pages.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0065 — Cycle de vie des pages : le brouillon de page","description":"Extrait de docs/adr/0065-cycle-de-vie-des-pages.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0065-cycle-de-vie-des-pages.md","filePath":"developpeurs/adr/0065-cycle-de-vie-des-pages.md"}'),o={name:"developpeurs/adr/0065-cycle-de-vie-des-pages.md"};function n(r,e,l,d,c,u){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0065--cycle-de-vie-des-pages--le-brouillon-de-page" tabindex="-1">ADR-0065 — Cycle de vie des pages : le brouillon de page <a class="header-anchor" href="#adr-0065--cycle-de-vie-des-pages--le-brouillon-de-page" aria-label="Permalink to &quot;ADR-0065 — Cycle de vie des pages : le brouillon de page {#adr-0065--cycle-de-vie-des-pages--le-brouillon-de-page}&quot;">​</a></h1><p><strong>Date :</strong> 4 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a>, action « Pages multilingues et brouillon de page » ; ses conséquences disaient « Les pages restent monolingues et publiques dès leur création : c&#39;est un choix de cycle de vie, à trancher à part » <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a> (résolution des adresses), <a href="/teuthis-cms-distribution/developpeurs/adr/0064-page-d-accueil-et-descripteur-de-site">ADR-0064</a> (page d&#39;accueil), <a href="/teuthis-cms-distribution/developpeurs/adr/0046-profils-d-usage-a-l-installation">ADR-0046</a> (pages de départ des profils)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Une page du Page Builder était en ligne dès sa création : <code>POST /pages</code> suffisait à la rendre lisible par <code>/public/resolve</code>, le plan de site, les menus et la recherche. Un webmaster ne pouvait donc ni préparer une rubrique avant de l&#39;ouvrir, ni la faire relire, ni la retirer sans la supprimer. Les contenus, eux, suivent depuis l&#39;Epic E4 un workflow éditorial complet (CDC §6), avec relecture et journal.</p><p>Le Product Owner a tranché deux points : ce lot livre <strong>le brouillon de page seulement</strong> — les pages multilingues viendront dans un lot suivant, la case de l&#39;ADR-0034 reste ouverte ; et le cycle de vie des pages est <strong>le workflow éditorial complet des contenus, réutilisé tel quel</strong>.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>La même machine à états, sans copie.</strong> Une page parcourt <code>brouillon → relecture → approuvée → publiée</code>, puis <code>dépubliée</code> ou reprise en brouillon, exactement selon <code>TRANSITIONS</code> (<code>app/lifecycle/workflow.py</code>). <code>app/page_builder/lifecycle.py</code> confie le statut de la page à <code>apply_transition</code>, qui refuse tout chemin absent (<code>draft → published</code> compris, 422) et pose seul <code>published_at</code>. Rien n&#39;est dupliqué : un chemin ajouté au workflow vaudra pour les pages comme pour les contenus.</li><li><strong>Stockage : deux colonnes sur <code>pages</code></strong>, <code>status</code> (défaut serveur <code>draft</code>) et <code>published_at</code>, et un index <code>(site_id, status)</code>. Pas de JSONB <code>settings</code> comme <code>content_entries</code> : une page n&#39;a pas de panneau de plugins à accueillir, et <code>status = &#39;published&#39;</code> est le filtre de chaque lecture publique d&#39;une page — il mérite une colonne indexée, pas une extraction JSON. Le défaut <code>draft</code> côté base fait qu&#39;une insertion qui oublie le statut produit une page cachée, jamais une page publiée.</li><li><strong>Journal : une table dédiée, <code>page_lifecycle_events</code></strong>, jumelle de <code>content_lifecycle_events</code> (mêmes colonnes, rôle attendu dans <code>payload.expected_role</code>), avec une <strong>clé étrangère réelle</strong> vers <code>pages</code> (<code>ON DELETE CASCADE</code>) et un index <code>(page_id, occurred_at)</code>. Généraliser la table des contenus aurait obligé à rendre nullable sa clé <code>content_entry_id</code>, sur laquelle la purge RGPD et le registre des traitements comptent. <code>GET /pages/{slug}/lifecycle-events</code> le lit par tranches (500 au plus).</li><li><strong>Permissions dédiées</strong> : <code>page.submit_for_review</code>, <code>page.review</code>, <code>page.publish</code>, et <code>PAGE_TRANSITION_PERMISSIONS</code> qui traduit chaque chemin (reprendre en brouillon une page dépubliée exige <code>page.write</code>, comme <code>content.update</code> pour un contenu). Elles sont accordées aux rôles livrés qui détiennent les permissions équivalentes sur les contenus : Admin et Editor les trois, Author la soumission, Reviewer la relecture, Translator aucune. Publier l&#39;actualité du jour et mettre en ligne une rubrique de l&#39;arborescence ne sont pas le même geste ; une organisation peut confier l&#39;un sans l&#39;autre. Dans un manifeste de plugin, la soumission est délégable, la relecture et la publication ne le sont pas (comme leurs équivalents de contenus). Un test vérifie que les deux tables de permissions couvrent exactement les chemins de la machine à états.</li><li><strong><code>POST /pages/{slug}/transitions</code></strong>, décalque de <code>POST /entries/{id}/transitions</code> et dans le même ordre de refus : 404 hors de l&#39;organisation, 422 pour un chemin inexistant (avant le RBAC), 403 en nommant la permission et le rôle attendu. Chaque transition réindexe la page <strong>et sa descendance</strong>.</li><li><strong>Invisibilité publique d&#39;une page non publiée, partout, et héritée.</strong> Une page est visible du public si elle <strong>et toute sa chaîne d&#39;ancêtres</strong> sont publiées — puis selon l&#39;ACL. C&#39;est la même règle d&#39;héritage que la restriction d&#39;accès : une page publiée sous un parent en brouillon reste invisible. Le point commun est <code>app/rbac/acl.py</code> : <code>PageNode</code> porte le statut (brouillon par défaut), <code>chain_is_published</code> et <code>page_is_visible</code> (publication puis <code>decide_access</code>) servent chaque surface : <ul><li><code>/public/resolve</code> : <strong>404 unique</strong>, celui d&#39;une page inconnue — ni servie, ni désignée par une redirection « page déplacée » ; la racine répond 404 si l&#39;accueil n&#39;est pas publié ;</li><li>descripteur <code>/public/site</code> : <code>home_path</code> et <code>home_page_id</code> à <code>null</code> (<code>public_home_page</code>) ;</li><li>plan de site XML (<code>app/content/sitemap.py</code>), arbre public <code>GET /sitemap</code>, pages sœurs et fil d&#39;Ariane, blocs menu automatique et manuel (<code>app/page_builder/page_tree.py</code>, réutilisé par <code>page_menu.py</code>) ;</li><li>recherche : <code>index_pages</code> n&#39;écrit une ligne que pour une page publiée sous une chaîne publiée, et retire les autres ; la transition réindexe le sous-arbre, si bien que dépublier une rubrique retire aussi ses pages filles ; la réindexation par lots applique la même règle ;</li><li>lectures publiques <code>GET /pages/{slug}</code>, <code>…/render</code>, <code>…/print-eligibility</code> et le vote d&#39;utilité : 404, avant toute question d&#39;ACL (un 401 dirait qu&#39;il existe quelque chose) ;</li><li>cache public : une erreur n&#39;est jamais mise en cache (<code>no-store</code>), une page publiée juste après n&#39;est donc pas masquée par un 404 gardé.</li></ul></li><li><strong>Le back-office voit tout.</strong> Un agent qui détient l&#39;une des permissions de pages (<code>page.write</code>, <code>page.submit_for_review</code>, <code>page.review</code>, <code>page.publish</code>) voit une page non publiée par les lectures de pages et l&#39;arbre (aperçu, <code>can_preview_unpublished</code>) ; <code>GET /pages</code> liste toutes les pages avec leur état.</li><li><strong>Page d&#39;accueil</strong> : <code>set_home_page</code> accepte une page non publiée — c&#39;est ainsi qu&#39;on prépare l&#39;ouverture d&#39;un site —, mais la racine répond 404 et le descripteur ne l&#39;annonce pas tant qu&#39;elle n&#39;est pas publiée, exactement comme pour un accueil restreint.</li><li><strong>Naissance des pages.</strong> <code>POST /pages</code> crée en brouillon, sans exception. Les <strong>pages de départ d&#39;un profil</strong> (<code>apply_profile</code>) sont publiées d&#39;office, par le chemin complet du workflow au nom du système (<code>publish_page_as_system</code>, trois lignes de journal <code>actor_kind = system</code>) : un site neuf doit répondre 200 à sa racine juste après l&#39;installation (recette v0.3.1). Les <strong>pages copiées par l&#39;usine à sites</strong> gardent l&#39;état publié de la page modèle (publiées par le même chemin système) ; toute autre page du modèle arrive en brouillon — une relecture vaut pour la page relue, pas pour sa copie. Une page <strong>poussée</strong> vers un autre site (<code>POST /replication/pages/{id}/push</code>) y naît en brouillon.</li><li><strong>Reprise (migration 0049) : toutes les pages existantes deviennent publiées</strong>, avec <code>published_at = created_at</code>. Avant cette migration, une page était en ligne dès sa création : la dater de sa création dit ce qui s&#39;est passé, là où « maintenant » ferait croire que tout le site a été mis en ligne le jour de la mise à jour. Aucune page existante n&#39;est cachée ; aucune ligne de journal n&#39;est inventée.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Un simple booléen « publiée »</strong></td><td>Pas de relecture, pas de journal : le contraire de la décision du Product Owner, et un second vocabulaire d&#39;état à côté de celui des contenus.</td></tr><tr><td><strong>Une machine à états propre aux pages</strong></td><td>Deux machines finissent par diverger ; une page pourrait un jour se publier sans relecture.</td></tr><tr><td><strong>JSONB <code>pages.settings</code> réutilisant <code>EntrySettings</code></strong></td><td>Rien d&#39;autre du panneau ne s&#39;applique à une page ; le filtre <code>status</code> de chaque lecture publique serait une extraction JSON non indexée.</td></tr><tr><td><strong>Généraliser <code>content_lifecycle_events</code> (colonne <code>page_id</code>, <code>content_entry_id</code> nullable)</strong></td><td>Affaiblit une clé étrangère dont dépendent la purge RGPD et le registre ; chaque lecteur du journal des contenus devrait filtrer les lignes de pages.</td></tr><tr><td><strong>Réutiliser les permissions des contenus</strong></td><td>Publier une fiche et ouvrir une rubrique deviendraient indissociables ; une organisation ne pourrait pas confier l&#39;un sans l&#39;autre.</td></tr><tr><td><strong>Une page publiée reste visible sous un parent non publié</strong></td><td>Une adresse contenant le slug d&#39;une page invisible, un fil d&#39;Ariane rattaché à un parent fantôme ; la restriction d&#39;accès, elle, s&#39;hérite déjà.</td></tr><tr><td><strong>Reprise avec <code>published_at = maintenant</code></strong></td><td>Fausse l&#39;histoire du site : toutes les pages sembleraient mises en ligne le jour de la mise à jour.</td></tr><tr><td><strong>Créer les pages de départ des profils directement publiées</strong></td><td>Un raccourci de création que <code>POST /pages</code> n&#39;aurait pas ; le journal ne dirait rien de leur publication.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><ul><li>Une page créée par <code>POST /pages</code> est <strong>invisible</strong> tant qu&#39;elle n&#39;a pas été soumise, approuvée et publiée. Les tests qui lisaient publiquement une page juste créée la publient par les transitions réelles (<code>publish_page</code> / <code>publish_created_page</code>, <code>tests/conftest.py</code>) ; aucune création publiée n&#39;existe pour les tests.</li><li>Le back-office affiche l&#39;état de chaque page en texte (liste des pages), et, sur la fiche, les boutons des transitions permises (composant <code>EntryWorkflow</code>, partagé avec les contenus) et le journal (<code>LifecycleEventLog</code>).</li><li>Le front public (<code>apps/front</code>) n&#39;a rien à changer : il ne voit que <code>/public/resolve</code>, qui répond 404 pour une page non publiée.</li><li>Les pages restent <strong>monolingues</strong> : le multilingue des pages reste à faire, dans un lot suivant ; la case de l&#39;ADR-0034 reste ouverte.</li><li>Aucune règle automatique (publication planifiée, dépublication à échéance) ne s&#39;applique aux pages : le moteur de règles reste celui des contenus.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Brouillon de page : migration 0049 (aller-retour <code>upgrade head</code> / <code>downgrade 0048</code> / <code>upgrade head</code> passé le 04/10/2026), service <code>app/page_builder/lifecycle.py</code>, route de transition et journal, permissions dédiées, invisibilité sur chaque surface publique, publication d&#39;office des pages de départ des profils. Preuve : <code>tests/test_cycle_de_vie_des_pages.py</code> (17 tests verts, une surface publique par test).</li><li>[x] Back-office : état en texte dans la liste des pages, transitions et journal sur la fiche d&#39;une page (relais <code>server/api/pages/[slug]/transitions.post.ts</code>, <code>lifecycle-events.get.ts</code>) ; paragraphe de la notice (§7.3). Les pages multilingues restent à faire : c&#39;est l&#39;action encore ouverte de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a>, qu&#39;on ne recompte pas ici.</li></ul>',13)])])}const b=t(o,[["render",n]]);export{g as __pageData,b as default};
